  session.payment_status='paid';await f.billing.event(f.event('checkout.session.completed',{id:session.id}));f.addInvoice('in_opaque_subject');await f.billing.event(f.event('invoice.paid',{id:'in_opaque_subject'}));assert.equal((await f.platform.dispatch(f.actor,'/me')).sub,subject);assert.equal((await f.platform.getOrder('inpay_in_opaque_subject')).sub,subject);
