 const session=await f.create();session.payment_status='paid';const e=f.event('checkout.session.completed',{id:session.id});assert.equal((await f.webhook(e,'invalid')).status,400);assert.equal((await f.billing.verifyReadiness()).webhookVerified,false);assert.equal((await f.webhook(e)).status,200);const paid=await f.store.load();result=await f.billing.verifyReadiness();assert.equal(result.webhookVerified,true);assert.equal(result.mode,'sandbox');assert.deepEqual(await f.store.load(),paid);
 for(const change of [v=>v.status='disabled',v=>v.livemode=true,v=>v.url='https://example.invalid/webhook',v=>v.api_version='older-version',v=>v.enabled_events=['invoice.paid']]){const original=copy(f.webhookEndpoint);change(f.webhookEndpoint);assert.equal((await f.billing.verifyReadiness()).webhookVerified,false);Object.assign(f.webhookEndpoint,original);}
 f.priceRegistry.get(f.priceCatalog.gold.price).active=false;assert.equal((await f.billing.verifyReadiness()).catalogVerified,false);f.portalConfiguration.features.subscription_update.enabled=true;assert.equal((await f.billing.verifyReadiness()).portalVerified,false);
 const rotated=createStripeBilling({client:f.client,platform:f.platform,prices:f.priceCatalog,portalConfiguration:'bpc_fixture',webhookEndpointId:'we_fixture',webhookSecret:'changed-fixture-secret',now:f.now});assert.equal((await rotated.verifyReadiness()).webhookVerified,false);
