test('early fraud warnings use fresh provider data and exact receipts without refunding or changing access',async()=>{
 const f=await fixture(),session=await f.create();session.payment_status='paid';await f.billing.event(f.event('checkout.session.completed',{id:session.id}));
 const payment=f.intents.get(session.payment_intent),warning={id:'issfr_fixture',object:'radar.early_fraud_warning',livemode:false,actionable:false,created:Math.floor(f.now()/1000),charge:copy(payment.latest_charge),payment_intent:payment.id};f.fraudWarnings.set(warning.id,warning);
 const received=[];f.platform.recordFraudWarning=async event=>{received.push(event);return{reviewRecorded:true};};
 const before=await f.platform.dispatch(f.actor,'/me'),event=f.event('radar.early_fraud_warning.created',{id:warning.id,actionable:true,payment_intent:'pi_forged'});
 await f.billing.event(event);assert.equal(received.length,1);assert.equal(received[0].verified,true);assert.equal(received[0].actionable,false);assert.equal(received[0].paymentIntentId,payment.id);assert.equal(received[0].chargeId,payment.latest_charge.id);assert.deepEqual(received[0].orderIds,[f.order.id]);assert.equal(typeof received[0].billingFence,'string');
 warning.actionable=true;await f.billing.event(event);assert.equal(received[1].actionable,true,'a retry reads current state instead of freezing the old warning');
 const after=await f.platform.dispatch(f.actor,'/me');assert.equal(after.creditsCents,before.creditsCents);assert.equal(after.availableCreditsCents,before.availableCreditsCents);assert.equal(f.calls.some(c=>c.type==='cancel'),false);
});
