 sub.status='active';f.addInvoice('in_warning_renewal');const payment=f.intents.get('pi_in_warning_renewal'),warning={id:'issfr_new_renewal',object:'radar.early_fraud_warning',livemode:false,actionable:true,created:Math.floor(f.now()/1000),charge:copy(payment.latest_charge),payment_intent:payment.id};f.fraudWarnings.set(warning.id,warning);let writes=0;f.platform.recordFraudWarning=async()=>{writes++;return{reviewRecorded:true};};const event=f.event('radar.early_fraud_warning.created',{id:warning.id});
 await assert.rejects(f.billing.event(event),code('payment_binding_missing'));assert.equal((await f.platform.dispatch(f.actor,'/me')).tier,'free');assert.equal(Object.keys((await f.platform.getBillingState()).invoiceReceipts||{}).length,0);assert.equal(writes,0);
 await f.billing.event(f.event('invoice.paid',{id:'in_warning_renewal'}));assert.equal((await f.platform.dispatch(f.actor,'/me')).tier,'gold');await f.billing.event(event);assert.equal(writes,1);assert.equal((await f.platform.dispatch(f.actor,'/me')).tier,'gold');
