test('a full refund is retried until recurring cancellation is independently confirmed',async()=>{
 const f=await fixture({kind:'subscription'}),session=await f.create();session.payment_status='paid';await f.billing.event(f.event('checkout.session.completed',{id:session.id}));
 const charge=f.intents.get(session.payment_intent).latest_charge;charge.amount_refunded=799;const event=f.event('charge.refunded',{id:charge.id,payment_intent:session.payment_intent}),cancel=f.client.subscriptions.cancel;f.client.subscriptions.cancel=async id=>({...copy(f.subscriptions.get(id)),status:'canceled'});
 await assert.rejects(f.billing.event(event),code('subscription_cancellation_incomplete'));assert.equal(f.subscriptions.get(session.subscription).status,'active');assert.equal((await f.platform.dispatch(f.actor,'/me')).tier,'free');
 f.client.subscriptions.cancel=cancel;await f.billing.event(event);assert.equal(f.subscriptions.get(session.subscription).status,'canceled');assert.equal((await f.platform.dispatch(f.actor,'/me')).tier,'free');
});
